import React, { useState, useEffect } from "react";
import { useHistory, useParams } from "react-router-dom";
import { getCarById, updateCar } from "../../services/ApiCar";

export default function CardEditVoiture() {
  const { id } = useParams();
  const history = useHistory();

  const [car, setCar] = useState({
    matricule: "",
    model: "",
    marque: "",
    libelle: "",
    prix: "",
    prix_jour: "",
    couleur: "",
    disponible: false,
    voiture_image: null,
  });

  const [errors, setErrors] = useState({});

  useEffect(() => {
    const fetchCar = async () => {
      try {
        const response = await getCarById(id);
        setCar(response);
      } catch (error) {
        console.error("Erreur de récupération :", error);
        alert("Erreur lors du chargement de la voiture");
      }
    };

    fetchCar();
  }, [id]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setCar({ ...car, [name]: value });
  };

  const handleFileChange = (e) => {
    setCar({ ...car, voiture_image: e.target.files[0] });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    let formErrors = {};
    if (!car.matricule.trim()) formErrors.matricule = "Matricule requis";
    if (!car.model.trim()) formErrors.model = "Modèle requis";
    if (!car.marque.trim()) formErrors.marque = "Marque requise";
    if (!car.libelle.trim()) formErrors.libelle = "Libellé requis";
    if (!car.prix) formErrors.prix = "Prix requis";
    if (!car.prix_jour) formErrors.prix_jour = "Prix par jour requis";
    if (!car.couleur.trim()) formErrors.couleur = "Couleur requise";

    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      return;
    }

    const formData = new FormData();
    Object.keys(car).forEach((key) => {
      formData.append(key, car[key]);
    });

    try {
      await updateCar(id, formData);
      history.push("/admin/Voiture");
    } catch (error) {
      console.error("Erreur lors de la mise à jour :", error);
      alert("Erreur lors de la mise à jour de la voiture");
    }
  };

  return (
    <div className="relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg bg-blueGray-100 border-0">
      <div className="rounded-t bg-white mb-0 px-6 py-6">
        <div className="text-center flex justify-between">
          <h6 className="text-blueGray-700 text-xl font-bold">Modifier la voiture</h6>
          <button
            className="bg-lightBlue-500 text-white font-bold uppercase text-xs px-4 py-2 rounded shadow hover:shadow-md"
            type="button"
            onClick={() => history.push("/admin/Voiture")}
          >
            Retour
          </button>
        </div>
      </div>

      {/* Réutilisation du même formulaire que pour l’ajout */}
      {/* Tu peux copier la structure de champs du composant d’ajout ici, et remplacer newCar par car */}

      {/* Pour ne pas dupliquer, tu veux que je fasse un composant réutilisable ? */}
    </div>
  );
}
